import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Product Scope And Architecture","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"en/architecture/lab-word.md","filePath":"en/architecture/lab-word.md"}'),i={name:"en/architecture/lab-word.md"};function o(s,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="product-scope-and-architecture" tabindex="-1">Product Scope And Architecture <a class="header-anchor" href="#product-scope-and-architecture" aria-label="Permalink to &quot;Product Scope And Architecture&quot;">​</a></h1><p>Lab Word is a laboratory digital twin. The application currently provides single-model viewing, a server-persisted Asset Library and versioned built-in definitions. Persistent worlds and server-owned virtual devices are the approved next stage. See the <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/CONTEXT.md" target="_blank" rel="noreferrer">glossary</a>.</p><h2 id="models-and-equipment" tabindex="-1">Models And Equipment <a class="header-anchor" href="#models-and-equipment" aria-label="Permalink to &quot;Models And Equipment&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab ──registers──&gt; Entity &lt;──defined by── Asset</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    └──represented by Scene Node &lt;──appearance── Asset Representation</span></span></code></pre></div><p>This is the Foundation V1 target relationship: an Equipment Model is a 3D representation, and an Equipment Instance is a device Entity. Scene Node identity and placement are independent of device identity. Multiple devices can share a model, and one device can have multiple nodes. The current single-model viewer does not establish these persistent objects or layouts.</p><h2 id="existing-implementation-and-planned-integration" tabindex="-1">Existing Implementation And Planned Integration <a class="header-anchor" href="#existing-implementation-and-planned-integration" aria-label="Permalink to &quot;Existing Implementation And Planned Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Current state</th><th>Future responsibility</th></tr></thead><tbody><tr><td>Universal shell, identity, membership, knowledge</td><td>Existing application code</td><td>Host Lab and provide shared capabilities</td></tr><tr><td>Lab Viewer and persistent Asset Library</td><td>Members/Agents share real files and APIs</td><td>Extend persistent worlds and multiple objects</td></tr><tr><td>Lab navigation and default entry after login</td><td>Integrated through explicit composition</td><td>Preserve shell and Lab ownership</td></tr><tr><td>Foundation V1</td><td>Experience accepted; spec/tickets published</td><td>Build persistent worlds and virtual devices</td></tr><tr><td>Physical devices and protocols</td><td>Future scope</td><td>Add source adapters and execution contracts</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>chooses the existing SaaS foundation: Lab owns equipment and layout behavior while Core owns common identity and membership. See <a href="./project-structure">project structure</a> for integration locations.</p><h2 id="presentation-boundaries" tabindex="-1">Presentation Boundaries <a class="header-anchor" href="#presentation-boundaries" aria-label="Permalink to &quot;Presentation Boundaries&quot;">​</a></h2><p>The current version inspects one self-contained GLB, with file selection/drop, automatic centering/framing, orbit/zoom/pan, click selection, return to preset and renderer metrics. Imports use Core&#39;s file lifecycle; Lab owns assets, representations and stable file associations. Other browsers and Agents can query the same catalog. Follow the <a href="./../tutorials/persistent-assets">persistent assets tutorial</a> for operations and recovery.</p><p>The current implementation preserves source scale, reports external-resource dependencies, absent geometry and decoder failures, and keeps the previous usable model on failure. Replacements and page exit release exclusive GPU resources; older loads cannot overwrite newer models. Multiple-instance work must retain these contracts.</p><p>Three.js code is loaded with the Lab page and checked against production bundle budgets. Preview builds and software-rendering measurements do not establish target-hardware performance.</p><h2 id="continue-development" tabindex="-1">Continue Development <a class="header-anchor" href="#continue-development" aria-label="Permalink to &quot;Continue Development&quot;">​</a></h2><p>Follow the <a href="./../guides/lab-viewer">viewer guide</a> for current behavior. Foundation V1 continues through <a href="https://github.com/CaiZongyuan/labworld/issues/1" target="_blank" rel="noreferrer">spec #1</a> and its implementation tickets; start with the <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/docs/handoffs/digital-twin-foundation-v1.md" target="_blank" rel="noreferrer">developer handoff</a>. <a href="./module-boundaries">Module boundaries</a> define ownership.</p><hr><p>Source version：<code>e6f80f5edb69</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/docs/architecture/lab-word.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,16)])])}const b=t(i,[["render",o]]);export{h as __pageData,b as default};
